"""Recall metric for a soccer highlight finder.

A highlight counts as found when a predicted clip overlaps it by more than
zero seconds. Each clip can be credited to at most one highlight, and the
score credits as many highlights as possible (maximum bipartite matching).
"""

from numbers import Real


def _validate(intervals, name):
    """Return intervals as a list of (start, end) pairs or raise ValueError."""
    checked = []
    for i, item in enumerate(intervals):
        try:
            start, end = item
        except (TypeError, ValueError):
            raise ValueError(f"{name}[{i}] must be a (start_s, end_s) pair, got {item!r}")
        for value in (start, end):
            if isinstance(value, bool) or not isinstance(value, Real):
                raise ValueError(f"{name}[{i}] contains a non-numeric value: {item!r}")
            if value != value:  # NaN
                raise ValueError(f"{name}[{i}] contains NaN: {item!r}")
        if start < 0 or end < 0:
            raise ValueError(f"{name}[{i}] has a negative time: {item!r}")
        if start > end:
            raise ValueError(f"{name}[{i}] has start > end: {item!r}")
        checked.append((start, end))
    return checked


def _overlaps(a, b):
    """True when half-open intervals a and b share more than zero seconds.

    Touching endpoints do not count, and a zero-length interval never
    overlaps anything.
    """
    return max(a[0], b[0]) < min(a[1], b[1])


def _max_matching(adj, n_clips):
    """Size of a maximum bipartite matching (Kuhn's algorithm, iterative DFS).

    adj[h] lists the clip indices that overlap highlight h.
    """
    match_clip = [-1] * n_clips  # clip index -> highlight index
    matched = 0

    for root in range(len(adj)):
        if not adj[root]:
            continue
        visited = [False] * n_clips
        stack = [(root, iter(adj[root]))]
        path_clips = []  # path_clips[i] is the clip taken from stack[i]
        found = False

        while stack:
            _, it = stack[-1]
            advanced = False
            for c in it:
                if visited[c]:
                    continue
                visited[c] = True
                path_clips.append(c)
                owner = match_clip[c]
                if owner == -1:
                    # Augment: every highlight on the path takes the clip it chose.
                    for (node, _), clip in zip(stack, path_clips):
                        match_clip[clip] = node
                    found = True
                else:
                    stack.append((owner, iter(adj[owner])))
                advanced = True
                break
            if found:
                break
            if not advanced:
                stack.pop()
                if path_clips:
                    path_clips.pop()

        if found:
            matched += 1

    return matched


def clip_recall(highlights, clips):
    """Fraction of highlights found by the predicted clips.

    Args:
        highlights: list of (start_s, end_s) ground-truth intervals.
        clips: list of (start_s, end_s) predicted intervals.

    A clip finds a highlight when they overlap by more than zero seconds.
    Each clip is credited to at most one highlight, and each highlight counts
    at most once; the assignment maximizes the number of highlights found.

    Returns:
        A float in [0.0, 1.0].

    Raises:
        ValueError: if highlights is empty, or any interval is malformed,
            negative, NaN, or has start > end.
    """
    hs = _validate(highlights, "highlights")
    cs = _validate(clips, "clips")
    if not hs:
        raise ValueError("highlights must contain at least one interval")

    adj = [[j for j, c in enumerate(cs) if _overlaps(h, c)] for h in hs]
    return _max_matching(adj, len(cs)) / len(hs)


if __name__ == "__main__":
    import unittest

    class ClipRecallTests(unittest.TestCase):
        def test_no_clips(self):
            self.assertEqual(clip_recall([(0, 5), (10, 15)], []), 0.0)

        def test_exact_match(self):
            self.assertEqual(clip_recall([(0, 5), (10, 15)], [(0, 5), (10, 15)]), 1.0)

        def test_partial_overlap(self):
            self.assertEqual(clip_recall([(10, 20)], [(19.5, 30)]), 1.0)

        def test_touching_endpoints_do_not_count(self):
            self.assertEqual(clip_recall([(10, 20)], [(0, 10), (20, 30)]), 0.0)

        def test_one_clip_covering_several_highlights_counts_once(self):
            self.assertEqual(clip_recall([(0, 5), (10, 15)], [(0, 20)]), 0.5)

        def test_whole_match_clip_counts_once(self):
            self.assertAlmostEqual(
                clip_recall([(0, 5), (10, 15), (20, 25)], [(0, 5400)]), 1 / 3
            )

        def test_several_clips_on_one_highlight(self):
            self.assertEqual(clip_recall([(0, 10), (20, 30)], [(1, 2), (3, 4), (5, 6)]), 0.5)

        def test_matching_beats_greedy(self):
            # Greedy A->c1 would leave B unmatched; the optimum matches both.
            highlights = [(0, 10), (0, 2)]
            clips = [(1, 3), (5, 6)]
            self.assertEqual(clip_recall(highlights, clips), 1.0)

        def test_matching_needs_augmenting_chain(self):
            highlights = [(0, 4), (3, 8), (7, 12)]
            clips = [(3.5, 3.9), (7.5, 7.9), (10, 11)]
            self.assertEqual(clip_recall(highlights, clips), 1.0)

        def test_zero_length_highlight_inside_clip(self):
            self.assertEqual(clip_recall([(2, 2)], [(1, 3)]), 0.0)

        def test_zero_length_clip_inside_highlight(self):
            self.assertEqual(clip_recall([(1, 3)], [(2, 2)]), 0.0)

        def test_floats(self):
            self.assertEqual(clip_recall([(1.25, 2.5)], [(2.49, 4.0)]), 1.0)

        def test_empty_highlights_raises(self):
            with self.assertRaises(ValueError):
                clip_recall([], [(0, 1)])

        def test_invalid_tuples_raise(self):
            for bad in [(5, 1), (-1, 2), (0, float("nan")), (1,), ("a", 2), None]:
                with self.subTest(bad=bad):
                    with self.assertRaises(ValueError):
                        clip_recall([bad], [])
                    with self.assertRaises(ValueError):
                        clip_recall([(0, 1)], [bad])

    unittest.main()
